"// 任何一条关闭路径都要摘掉 ESC 监听 (以前只有 ESC 那条摘, 点按钮/点遮罩关就永久留一个,": "// Every close path must remove the ESC listener (previously only the ESC path removed it; closing via button/mask left one behind forever,",
