"// 优先使用仓库数据（动态，包含所有策略）": "// Prefer repository data (dynamic, includes all strategies)",
"// 优先显示个股标准参数的 WF 结果（custom_params 升级后的参数）": "// Prefer showing the WF result for the stock's standard parameters (parameters upgraded via custom_params)",
"// 优先本地缓存, 缓存缺失时从服务器直接拉 (创建后立即编辑等场景)": "// Prefer the local cache; pull directly from the server when the cache is missing (e.g. editing right after creation)",
"// 优先级: custom(个股标准) > standard(通用标准)": "// Priority: custom (per-stock standard) > standard (universal standard)",
"// 优化是 CPU 密集的: 一次跑会起满一池 worker, 跑完还要再起一个 WF 池验证.": "// Optimization is CPU-intensive: a single run fills a whole worker pool, and when it finishes another WF pool is spun up for validation.",
"// 优化结束 (成功/失败/取消都算): 解锁 + 恢复按钮": "// Optimization finished (success/failure/cancel all count): unlock + restore the button",
"// 优化进行中时把入口按钮置灰, 从视觉上断掉\"再点一次\"的念头": "// Gray out the entry button while optimization is running, visually cutting off the \"run it again\" impulse",
