"// 更新持仓面板中的信号状态": "// Update signal status in the Positions panel",
"// 更新按钮高亮": "// Update button highlighting",
"// 更新本地evalData中的状态（不重新跑评测）": "// Update the status in the local evalData (without re-running the evaluation)",
"// 最后一根 bar 是不是\"今天\" — 是则说明当前用的是盘中未走完的 bar": "// Whether the last bar is \"today\" — if so, the current bar is an unfinished intraday one",
"// 最直接的后果是\"在这一行选了股票池, 点的却是只认 Symbol 的按钮\"(或反过来).": "// The most direct consequence: \"you picked a stock pool on this row but clicked a button that only honors Symbol\" (or the reverse).",
