"// 标题把两段都写清楚: 画了多少根 / 信号只算了哪一段": "// The title spells out both segments: how many bars were drawn / which segment the signals were computed on",
"// 校验全过了才上锁, 免得中途 return 把标志卡死": "// Take the lock only after all checks pass, so an early return doesn't leave the flag stuck",
