"// 样本外模式下, 表里每一个数都只在**持出段**上算(含基线), 口径写进表头,": "// In out-of-sample mode, every number in the table is computed on the **holding segment** only (baseline included); state that basis in the table header,",
"// 根据当前 Top5 数据源决定用哪套参数加载图表": "// Decide which parameter set to load the chart with, based on the current Top5 data source",
