"// 每个池记住排序方式 (localStorage, 本机偏好; 顺序本身存在服务端池里)": "// Each pool remembers its sort mode (localStorage, a local preference; the order itself lives in the server-side pool)",
"// 每个阶段记住上一次拿到的 total。后端在阶段切换的缝隙里会短暂只发": "// Each stage remembers the last total it received. In stage-switch gaps the backend briefly sends only",
