"// 池内该 symbol 的\"有效置顶列表\" (pinned 里已不在池中的要剔掉) — 全站唯一口径": "// The symbol's \"effective pinned list\" within the pool (drop pinned entries no longer in the pool) — the one canonical definition site-wide",
