"// 渲染可用变量 chips + 安装文本变化监听器": "// Render the available variable chips + install text-change listeners",
"// 点击警报：自动填入股票代码，执行Run Comparison更新Top6策略栏，然后切换到对应K线周期验证信号": "// Click an alert: auto-fill the ticker, run Run Comparison to update the Top6 strategy bar, then switch to the matching K-Line period to verify the signal",
"// 点外面 / ESC / 滚动 / 改窗口 → 关": "// Click outside / ESC / scroll / resize → close",
