"// 状态是渲染那一刻抄的快照。不刷的话点完只有一句 toast, 按钮纹丝不动。": "// The state is a snapshot taken at render time. Without a refresh, a click yields one toast while the button doesn't budge.",
"// 现在 period 决定信号(跟排名表一致), chart_period 只决定画多少根背景K线,": "// Now period drives the signals (consistent with the ranking table), while chart_period only decides how many background K-Line bars are drawn,",
"// 现在按\"发生了什么 / 影响是什么 / 怎么办\"三句话说清楚。": "// Now it's spelled out in three sentences: \"what happened / what the impact is / what to do\".",
"// 现由": "// Now by",
"// 用户以为选了\"只看成功率\"就生效了。": "// The user assumes selecting \"success rate only\" took effect.",
"// 用户停在确认框上的这段时间里别人可能已经开跑了": "// While the user sits on the confirmation dialog, someone else may already have started a run",
"// 用户反馈: 点了「激活」「删除」只弹一句成功, 按钮和那一行纹丝不动, 看不出": "// User feedback: clicking \"Activate\" or \"Delete\" pops one success line while the button and row don't budge — no way to tell",
"// 用户反馈：\"评测排名，以前是表格...不是你现在这种文本的样子\"。": "// User feedback：\"Evaluation Ranking, it used to be a table... not the text-like thing it is now\".",
"// 用户只能以为 13 个都成了, 直到在优化候选表里发现少了 6 个。": "// The user can only assume all 13 succeeded, until finding 6 missing in the optimization candidates table.",
"// 用户显式改排序 (下拉 / 点表头) 才落盘偏好 — 以前放在 render 里, 搜索框每敲一个字都写一次": "// Persist the preference only on an explicit sort change (dropdown / header click) — it used to live in render, writing once per keystroke in the search box",
"// 用户等 10 分钟什么都看不到。": "// The user waits 10 minutes and sees nothing.",
