"// 连错 5 次(约 10 秒)才认输。": "// giving up only after 5 consecutive misses (about 10 seconds).",
"// 选中优先级: 原来选的 → 上次记住的 → MYPOOL → 第一个": "// Selection priority: previously selected → last remembered → MYPOOL → the first one",
"// 选了股票池 → 用池的 market (onPoolSelect 已负责); 否则按 symbol 形态推断.": "// Pool selected → use the pool's market (onPoolSelect handles that); otherwise infer from the symbol's format.",
