"// 那句提示就是骗人的。真停下来了面板会进终态, 按钮本来就会隐藏。": "// That message is simply a lie. If it truly stopped, the panel reaches a terminal state and the button hides anyway.",
"// 那张卡还在, 用户以为\"没删掉\".": "// The card is still there; the user thinks \"it wasn't deleted\".",
"// 配置），强制调一次 LLM 并发新的 Stage 3 记录到同一 cycle。": "// config), force one LLM call and send a new Stage 3 record to the same cycle.",
"// 采用服务端返回值 (它会把 pinned 里已移除的 symbol 剔掉), 别只改本地 symbols": "// Use the server's return value (it drops symbols removed from pinned); don't just mutate the local symbols",
"// 重复点会让进程池叠加, 12 核叠三层 = 29 个 worker 抢 12 核, 整个服务被拖垮.": "// Repeat clicks stack process pools: 3 layers on 12 cores = 29 workers fighting over 12 cores, dragging the whole service down.",
