"// 面板右上角的 ? 说明按钮 — 纯常量, 别在每次重绘里重新拼这 1.3KB 字符串": "// The ? help button at the panel's top-right — a pure constant; don't re-assemble this 1.3KB string on every repaint",
"// 面板就停在第一段的终态(比如 13/13)干等二十来秒, 看着就是卡死。": "// The panel just sits at the first segment's terminal state (say 13/13) waiting twenty-odd seconds — it reads as hung.",
"// 面板看起来就是来回跳。按服务端的 updated_at 丢弃过期响应。": "// The panel visibly jumps back and forth. Discard stale responses by the server's updated_at.",
