"2. 目标函数 = 前 4 段的「平均成功率 − 0.5×段间标准差」×样本折扣（减标准差是为了淘汰「某一段特别好、其余稀烂」的参数；一段里不足 3 个信号的不计入平均）；": "2. Objective function = the first 4 segments' \"average success rate − 0.5×cross-segment standard deviation\" × sample discount (subtracting the standard deviation weeds out parameters that are \"great in one segment and terrible in the rest\"; a segment with fewer than 3 signals is excluded from the average);",
