"：每只股票一次 LLM 调用（约 5-15s），50 只 ≈ 5-12 分钟。weight 模式每次扫描都跑 LLM，必然比 off 慢得多。": "：one LLM call per stock（about 5-15s）; 50 stocks ≈ 5-12 minutes. In weight mode every scan runs the LLM, so it is inevitably much slower than off.",
"：等待中，倒计时到下一次自动扫": "：waiting, counting down to the next automatic scan",
"：策略用什么粒度的 K 线找信号 → 找到的 alerts 是什么时间尺度的。": "：the K-Line granularity the strategy uses to find signals → the time scale of the alerts found.",
"：股票池或策略为空": "：stock pool or strategy is empty",
"：自动扫描配": "：auto scan paired with",
"：自启动以来累计。": "：cumulative since startup.",
"：该 worker 注册时声明能跑的 provider 列表。": "：the list of providers this worker declared it can run at registration.",
"：过去 1 小时已完成任务的": "：tasks completed in the past 1 hour",
"：过去 24 小时按状态分组的任务总数。": "：total tasks in the past 24 hours, grouped by status.",
"：选股票池回测会使用": "：backtests on the selected stock pool will use",
"：选越多覆盖越全，但单次扫描耗时也越久（线性叠加）。如果只关心特定市场的新闻，单选最快；如果要「全市场新闻雷达」，全选。": "：the more you select, the fuller the coverage, but each scan also takes longer（linearly additive）. If you only care about news in a specific market, selecting just one is fastest; for a \"whole-market news radar\", select all.",
"：配置写到 news_buffer_config.json 的 auto_scan 块。重启服务后会从配置自动恢复。": "：the config is written to the auto_scan block of news_buffer_config.json. After the service restarts, it is automatically restored from the config.",
"：默认 70（对应「mildly bullish」以上）。改阈值只影响后续打分；已入池的股票不会被踢出。": "：defaults to 70（\"mildly bullish\" and above）. Changing the threshold only affects subsequent scoring; stocks already in the pool are not removed.",
"：默认是当前服务器自己的": "：defaults to the current server's own",
