": 每只股票单独排名. 从勾选 owner 的活跃策略里, 各在这只股上跑 2 年回测, 按该股年化收益取前 N. 按周期自动 rebalance. NVDA 的前 3 跟 AAPL 的前 3 可能完全不同 — 每股独立榜单.": ": Each stock gets its own ranking. From the active strategies of the checked owners, a 2-year backtest is run per stock, keeping the top N by that stock's annualized return. Rebalances automatically on schedule. NVDA's top 3 can be totally different from AAPL's top 3 — an independent leaderboard per stock.",
": 每笔开仓 = 当前现金 × 后面的百分比. 简单可预期.": ": Each new position = current cash × the percentage below. Simple and predictable.",
": 池详情栏也有 [🔄 Rebalance] 按钮可以立即跑一次, 不等到期。": ": The pool detail panel also has a [🔄 Rebalance] button to run it immediately instead of waiting for the interval.",
