"。如果环境变量": ". If the environment variable",
"。实测": ". Measured",
"。得分 × min(信号数/30, 1) 做样本折扣，否则优化器会把参数调到几乎不出信号（2 个信号全中 = 100%）。缺点：全程只有一套数据，优化器见过全部行情，报出来的成功率": ". Score × min(signals/30, 1) applies a sample discount, otherwise the optimizer tunes parameters to emit almost no signals（2 signals all correct = 100%）. Drawback：there is only one dataset the whole way, the optimizer has seen all the price action, so the reported success rate",
"。打分后凡是低于「最低打分」阈值的 alert 全部被淘汰；": ". After scoring, every alert below the \"minimum score\" threshold is eliminated;",
"。每只股票拉新闻 → LLM 打 0-100 分 → alert 带上 news 字段；所有 alerts 都保留，按分数排序。": ". Pull news for each stock → LLM scores it 0-100 → the alert carries a news field; all alerts are kept, sorted by score.",
"。算出的仓位低于此值时抬到此值。": ". If the calculated position is below this value, it is raised to this value.",
"。算出的仓位高于此值时削到此值。": ". If the calculated position is above this value, it is cut down to this value.",
