"分出卖对/卖早的卖点里, 中位数第几根出的结果。括号里是窗口内分出胜负的比例。&#10;&#10;注: 「最优窗口」在先到先判下没有意义 —— 成功率随窗口单调变化, 它永远等于试过的最长窗口。": "Among sell points that ended as correct-sell or sold-too-early, the median bar on which the outcome was decided. The parentheses show the share of sell points resolved within the window.&#10;&#10;Note: \"Optimal window\" is meaningless under first-hit-wins — the success rate varies monotonically with the window, so it always equals the longest window tried.",
"分出胜负的买点里, 中位数第几根出的结果。括号里是窗口内分出胜负的比例(其余是两边都没碰到, 算失败)。&#10;&#10;注: 「最优窗口」在先到先判下没有意义 —— 成功率随窗口单调递增, 它永远等于试过的最长窗口。": "Among buy points with a resolved outcome, the median bar on which it was decided. The parentheses show the share resolved within the window (the rest hit neither side and count as failures).&#10;&#10;Note: \"Optimal window\" is meaningless under first-hit-wins — the success rate increases monotonically with the window, so it always equals the longest window tried.",
