"想彻底避开这个问题，就用更细的周期（比如日线信号改用 5m/15m 线来判定）。": "To avoid this completely, judge with a finer interval (e.g. judge daily signals on 5m/15m bars).",
"注意：N 给太小会让买点数不够，综合评分里的样本折扣会把分数压下去（买点数 < 30 会标 ⚠）。": "Note: if N is too small there won't be enough buy points, and the sample discount in the overall score will pull the score down (fewer than 30 buy points is flagged ⚠).",
"—— 「搜索段」那列是优化器见过的、天然好看, 只用来看落差。\n      落差 > 15pp 或 持出段 < 40% 的策略": "— the \"search segments\" column is data the optimizer has seen, so it naturally looks good; use it only to read the gap.\n      Strategies with gap > 15pp or holdout < 40%",
"。N 或区间给太小会让卖点数不够，样本太少的成功率不能当真。": ". If N or the date range is too small there won't be enough sell points, and a success rate from too few samples can't be trusted.",
"：搜索段=优化器见过的 4 段；持出段=封存不给看的 2 段；pp=百分点（57%−48%=9pp）。": ": search segments = the 4 segments the optimizer saw; holdout segments = the 2 sealed segments it never saw; pp = percentage points (57% − 48% = 9pp).",
"存的, 切到别的市场标签看到的是那个市场自己的值。": " is stored per market; switching to another market tab shows that market's own value.",
"（BUY 监控）：扫描设置里勾选的本市场股票池的并集，扫描寻找新买点。": " (BUY monitoring): the union of this market's stock pools checked in the scan settings, scanned for new buy points.",
"/30 打折 —— 样本太少, 成功率再高也不能当真": "/30 discount — too few samples; a high success rate can't be trusted",
"已置顶 · 只能在置顶组内调顺序 (要拖到下面先右键取消置顶)": "Pinned · can only be reordered within the pinned group (right-click to unpin before dragging it below)",
"记录数 = 触发的策略数 × 命中的股票数（覆盖所有当前 owner 过滤后的策略）。": "Record count = triggered strategies × matched stocks (covering all strategies after the current owner filter).",
"设置改动后点 💾 保存生效，会绑定到当前市场标签的 localStorage。": "After changing settings, click 💾 Save & Apply; they are stored for the current market tab.",
"注意: 买点/卖点的独立参数(signal_params)不受这个开关影响, 它们不过 WF。": "Note: separate buy/sell point parameters (signal_params) are not affected by this switch; they don't go through WF.",
"（SELL 监控）：当前市场模拟交易的持仓（按 symbol+market 去重），仅对持仓股扫卖出信号。": " (SELL monitoring): this market's paper-trading positions (de-duplicated by symbol+market); only held stocks are scanned for sell signals.",
"3. 后台 daemon 下一轮按「刷新频率」扫这些池里的股票, 出 Stage 1 原始信号。": "3. On its next round (per the refresh rate) the background daemon scans the stocks in these pools and emits Stage 1 raw signals.",
"一条记录覆盖多个 group（同桶合批扫描），数量通常 ≤ 5 个/cycle。": "One record covers several groups (batched scan of the same bucket); usually ≤ 5 per cycle.",
"典型用法：只跑 Claude 生成的策略 → 勾 Claude 单项": "Typical use: to run only Claude-generated strategies → check just Claude",
"标签手动改的 > 65 只 seeded 常见空头利率 > 此池默认值 (兜底).": " tab, manual edits > 65 seeded common short-borrow rates > this pool's default (fallback).",
"：审计 ring 中所有 cycle 的去重数（不限市场）。": ": number of distinct cycles in the audit ring (all markets).",
"少于 30 根 K 线，不足以回测，排名直接跳过。": "Fewer than 30 K-line bars — not enough to backtest, so it is skipped in the ranking.",
"当前市场最近所有扫描产出的原始信号（Stage 1）累计在这里。": "Raw signals (Stage 1) from all recent scans of the current market accumulate here.",
"每行带 cycle_id 来源（auto / manual / global）方便溯源。": "Each row carries its cycle_id source (auto / manual / global) for tracing.",
": IB Gateway 实盘探测 (HTB 标记 → 25%) > 用户在": ": IB Gateway live probe (HTB flag → 25%) > user edits in the",
"只 | 评分: 0.40×收益 + 0.25×Sharpe/3 + 0.20×(1-回撤) + 0.10×胜率 + 0.05×盈亏比/5": " stocks | Score: 0.40×Return + 0.25×Sharpe/3 + 0.20×(1−Drawdown) + 0.10×Win rate + 0.05×Profit factor/5",
"— 半数以上 (>50%) 说 EXECUTE 就 EXECUTE. 兼顾灵活.": "— if more than half (>50%) say EXECUTE, execute. Balances flexibility.",
"成功判定：MFE > 目标% 且 MAE < 上限%": "Success rule: MFE > target% and MAE < limit%",
